{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-YwRm4C/src/align.js","content":"/**
 * Aligns one side's document against the base with a longest common
 * subsequence over whole lines, and reports the stretches the subsequence
 * does not cover as changes.
 */

/**
 * Computes the changes needed to turn `base` into `side`. Each change is a
 * run of base lines (`baseStart` to `baseEnd`) replaced by a run of the
 * side's lines (`sideStart` to `sideEnd`, kept as `lines`). An insertion has
 * an empty base run and a deletion an empty side run.
 *
 * The longest common subsequence is found by walking both documents from
 * the start: a match is taken whenever the current lines are equal, and
 * otherwise the side whose remaining subsequence (after dropping its
 * current line) is at least as long as the other's is advanced, preferring
 * to advance the base on a tie. This picks, among equally long common
 * subsequences, the one whose matches come earliest.
 */
export function computeChanges(base, side) {
  const n = base.length
  const m = side.length

  // dp[i][j] holds the length of the longest common subsequence of
  // base[i:] and side[j:].
  const dp = new Array(n + 1)
  for (let i = 0; i <= n; i++) {
    dp[i] = new Array(m + 1).fill(0)
  }
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      dp[i][j] = base[i] === side[j] ? dp[i + 1][j + 1] + 1 : Math.max(dp[i + 1][j], dp[i][j + 1])
    }
  }

  const changes = []
  let i = 0
  let j = 0
  let baseStart = 0
  let sideStart = 0

  while (i < n && j < m) {
    if (base[i] === side[j]) {
      if (i > baseStart || j > sideStart) {
        changes.push(makeChange(baseStart, i, sideStart, j, side))
      }
      i++
      j++
      baseStart = i
      sideStart = j
    } else if (dp[i + 1][j] >= dp[i][j + 1]) {
      i++
    } else {
      j++
    }
  }

  if (n > baseStart || m > sideStart) {
    changes.push(makeChange(baseStart, n, sideStart, m, side))
  }

  return changes
}

function makeChange(baseStart, baseEnd, sideStart, sideEnd, side) {
  return { baseStart, baseEnd, sideStart, sideEnd, lines: side.slice(sideStart, sideEnd) }
}
"}

