{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e3-attempts-t5-20260919T123108Z/cell-YwRm4C/src/regions.js","content":"/**
 * Groups the changes from both sides into regions of the base document, and
 * resolves each region to the lines it should merge to.
 */

/**
 * Merges `mineChanges` and `theirsChanges` (each sorted by base start, as
 * `computeChanges` produces) into one list ordered by base start, with a
 * change from mine before a change from theirs when they start at the same
 * place.
 */
function mergeChanges(mineChanges, theirsChanges) {
  const combined = []
  let mi = 0
  let ti = 0
  while (mi < mineChanges.length && ti < theirsChanges.length) {
    if (mineChanges[mi].baseStart <= theirsChanges[ti].baseStart) {
      combined.push({ side: 'mine', change: mineChanges[mi++] })
    } else {
      combined.push({ side: 'theirs', change: theirsChanges[ti++] })
    }
  }
  while (mi < mineChanges.length) combined.push({ side: 'mine', change: mineChanges[mi++] })
  while (ti < theirsChanges.length) combined.push({ side: 'theirs', change: theirsChanges[ti++] })
  return combined
}

/**
 * Builds one side's replacement lines for a region: the base lines it
 * begins before its first change and ends after its last, with each of its
 * own changes' lines spliced in and the base lines between them kept where
 * that side made no change.
 */
function sideLines(changes, start, end, base) {
  if (changes.length === 0) {
    return base.slice(start, end)
  }
  let result = []
  let cursor = start
  for (const change of changes) {
    result = result.concat(base.slice(cursor, change.baseStart), change.lines)
    cursor = change.baseEnd
  }
  result = result.concat(base.slice(cursor, end))
  return result
}

/**
 * Walks the base document, splitting it into stable regions (kept
 * unchanged) and change regions (one or more overlapping changes from
 * either side, absorbed while each next change starts at or before the
 * region's current end), each carrying the mine/base/theirs lines it spans.
 */
export function buildRegions(base, mineChanges, theirsChanges) {
  const combined = mergeChanges(mineChanges, theirsChanges)
  const regions = []
  let cursor = 0
  let idx = 0

  while (idx < combined.length) {
    let regionStart = combined[idx].change.baseStart
    let regionEnd = combined[idx].change.baseEnd
    const touching = [combined[idx]]
    idx++
    while (idx < combined.length && combined[idx].change.baseStart <= regionEnd) {
      regionEnd = Math.max(regionEnd, combined[idx].change.baseEnd)
      touching.push(combined[idx])
      idx++
    }

    if (regionStart > cursor) {
      regions.push({ kind: 'stable', start: cursor, end: regionStart })
    }

    const mineTouching = touching.filter(t => t.side === 'mine').map(t => t.change)
    const theirsTouching = touching.filter(t => t.side === 'theirs').map(t => t.change)
    regions.push({
      kind: 'change',
      start: regionStart,
      end: regionEnd,
      mineLines: sideLines(mineTouching, regionStart, regionEnd, base),
      baseLines: base.slice(regionStart, regionEnd),
      theirsLines: sideLines(theirsTouching, regionStart, regionEnd, base),
    })
    cursor = regionEnd
  }

  if (cursor < base.length) {
    regions.push({ kind: 'stable', start: cursor, end: base.length })
  }

  return regions
}

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false
  }
  return true
}

/**
 * Resolves a change region: `both` when mine and theirs made the same
 * change, `mine` or `theirs` when only that side changed, and `conflict`
 * when both changed and disagree.
 */
export function resolveRegion(region) {
  const { mineLines, baseLines, theirsLines } = region
  if (arraysEqual(mineLines, theirsLines)) {
    return { type: 'both', lines: mineLines }
  }
  if (arraysEqual(mineLines, baseLines)) {
    return { type: 'theirs', lines: theirsLines }
  }
  if (arraysEqual(theirsLines, baseLines)) {
    return { type: 'mine', lines: mineLines }
  }
  return { type: 'conflict' }
}
"}

